import CalculationError from "@entities/CalculationError"
import calculate from "./calculate"
import toLatex from "@testing/toLatex"

const strip = (value: string) => value.replaceAll(/\s+/g, "")

function latexOf(step: Parameters<typeof toLatex>[0]){
	return strip(toLatex(step))
}

// Expected steps were generated by the implementation that existed before version 3.0.0, which did the
// arithmetic with floating-point numbers. Only the cases where that did not add rounding noise are listed.
// Differences from it: a plain squared distance has no parentheses, numbers between 0.001 and 1 are
// written as decimals instead of powers of ten, and the charge steps do not repeat the quotient twice.
const legacyCases = [
	{
		id: "force",
		constant: "9",
		values: {
			charge1: "1",
			charge2: "2",
			distance: "3.5"
		},
		steps: [
			String.raw`F = \dfrac{9 \times 10^{9} \times 1 \times 2}{3.5^{2}}`,
			String.raw`F = \dfrac{9 \times 10^{9} \times 2}{12.25}`,
			String.raw`F = \dfrac{1.8 \times 10^{10}}{12.25}`,
			String.raw`F = 1.4693877551 \times 10^{9}\ N`
		]
	},
	{
		id: "force",
		constant: "8.9",
		values: {
			charge1: "1.6e-19",
			charge2: "1.6e-19",
			distance: "7e-9"
		},
		steps: [
			String.raw`F = \dfrac{8.9 \times 10^{9} \times 1.6 \times 10^{-19} \times 1.6 \times 10^{-19}}{(7 \times 10^{-9})^{2}}`,
			String.raw`F = \dfrac{8.9 \times 10^{9} \times 2.56 \times 10^{-38}}{4.9 \times 10^{-17}}`,
			String.raw`F = \dfrac{2.2784 \times 10^{-28}}{4.9 \times 10^{-17}}`,
			String.raw`F = 4.64979591837 \times 10^{-12}\ N`
		]
	},
	{
		id: "force",
		constant: "9",
		values: {
			charge1: "1",
			charge2: "1",
			distance: "1"
		},
		steps: [
			String.raw`F = \dfrac{9 \times 10^{9} \times 1 \times 1}{1^{2}}`,
			String.raw`F = \dfrac{9 \times 10^{9} \times 1}{1}`,
			String.raw`F = \dfrac{9 \times 10^{9}}{1}`,
			String.raw`F = 9 \times 10^{9}\ N`
		]
	},
	{
		id: "charge",
		constant: "9",
		values: {
			force: "+4",
			charge2: "7e-9",
			distance: "1e3"
		},
		steps: [
			String.raw`4 = 9 \times 10^{9} \times \dfrac{q \times 7 \times 10^{-9}}{1000^{2}}`,
			String.raw`\dfrac{4}{9 \times 10^{9}} = \dfrac{q \times 7 \times 10^{-9}}{1 \times 10^{6}}`,
			String.raw`q = \dfrac{4 \times 1 \times 10^{6}}{9 \times 10^{9} \times 7 \times 10^{-9}}`,
			String.raw`q = \dfrac{4 \times 10^{6}}{63}`,
			String.raw`q = 6.34920634921 \times 10^{4}\ C`
		]
	},
	{
		id: "charge",
		constant: "8.9",
		values: {
			force: "1e3",
			charge2: "2",
			distance: "1.6e-19"
		},
		steps: [
			String.raw`1000 = 8.9 \times 10^{9} \times \dfrac{q \times 2}{(1.6 \times 10^{-19})^{2}}`,
			String.raw`\dfrac{1000}{8.9 \times 10^{9}} = \dfrac{q \times 2}{2.56 \times 10^{-38}}`,
			String.raw`q = \dfrac{1000 \times 2.56 \times 10^{-38}}{8.9 \times 10^{9} \times 2}`,
			String.raw`q = \dfrac{2.56 \times 10^{-35}}{1.78 \times 10^{10}}`,
			String.raw`q = 1.43820224719 \times 10^{-45}\ C`
		]
	},
	{
		id: "distance",
		constant: "9",
		values: {
			force: "1",
			charge1: "2",
			charge2: "3.5"
		},
		steps: [
			String.raw`1 = \dfrac{9 \times 10^{9} \times 2 \times 3.5}{d^{2}}`,
			String.raw`d^{2} = \dfrac{9 \times 10^{9} \times 7}{1}`,
			String.raw`d^{2} = \dfrac{6.3 \times 10^{10}}{1}`,
			String.raw`d = \sqrt{6.3 \times 10^{10}}`,
			String.raw`d = 2.5099800796 \times 10^{5}\ m`
		]
	},
	{
		id: "distance",
		constant: "8.9",
		values: {
			force: "2.5e10",
			charge1: "1e-6",
			charge2: "1.6e-19"
		},
		steps: [
			String.raw`2.5 \times 10^{10} = \dfrac{8.9 \times 10^{9} \times 1 \times 10^{-6} \times 1.6 \times 10^{-19}}{d^{2}}`,
			String.raw`d^{2} = \dfrac{8.9 \times 10^{9} \times 1.6 \times 10^{-25}}{2.5 \times 10^{10}}`,
			String.raw`d^{2} = \dfrac{1.424 \times 10^{-15}}{2.5 \times 10^{10}}`,
			String.raw`d = \sqrt{5.696 \times 10^{-26}}`,
			String.raw`d = 2.38662942243 \times 10^{-13}\ m`
		]
	},
	{
		id: "distance",
		constant: "9",
		values: {
			force: "+4",
			charge1: "1",
			charge2: "1"
		},
		steps: [
			String.raw`4 = \dfrac{9 \times 10^{9} \times 1 \times 1}{d^{2}}`,
			String.raw`d^{2} = \dfrac{9 \times 10^{9} \times 1}{4}`,
			String.raw`d^{2} = \dfrac{9 \times 10^{9}}{4}`,
			String.raw`d = \sqrt{2.25 \times 10^{9}}`,
			String.raw`d = 4.74341649025 \times 10^{4}\ m`
		]
	},
	{
		id: "distance",
		constant: "8.99",
		values: {
			force: "1e3",
			charge1: "7e-9",
			charge2: "7e-9"
		},
		steps: [
			String.raw`1000 = \dfrac{8.99 \times 10^{9} \times 7 \times 10^{-9} \times 7 \times 10^{-9}}{d^{2}}`,
			String.raw`d^{2} = \dfrac{8.99 \times 10^{9} \times 4.9 \times 10^{-17}}{1000}`,
			String.raw`d^{2} = \dfrac{4.4051 \times 10^{-7}}{1000}`,
			String.raw`d = \sqrt{4.4051 \times 10^{-10}}`,
			String.raw`d = 2.09883300908 \times 10^{-5}\ m`
		]
	}
] as const

describe("calculate", () => {
	it.each(legacyCases)("matches the previous steps: $id $values", ({ id, constant, values, steps }) => {
		const calculation = calculate(id, constant, values)

		expect(calculation.steps.map(latexOf)).toEqual(steps.map(strip))
	})

	it("writes a plain squared distance without parentheses", () => {
		const [first] = calculate("force", "9", { charge1: "20", charge2: "3", distance: "2" }).steps

		expect(latexOf(first)).toContain("{2^{2}}")
	})

	it("keeps the parentheses around powers of ten and negative numbers", () => {
		const [first] = calculate("charge", "9", { force: "1", charge2: "2", distance: "1e-6" }).steps

		expect(latexOf(first)).toContain(String.raw`{(1\times10^{-6})^{2}}`)
	})

	it("ignores the sign of the charges", () => {
		const positive = calculate("force", "9", { charge1: "2", charge2: "3", distance: "4" })
		const negative = calculate("force", "9", { charge1: "-2", charge2: "-3", distance: "4" })

		expect(negative.steps.slice(1)).toEqual(positive.steps.slice(1))
	})

	it("is exact, with no floating-point noise", () => {
		const { steps } = calculate("charge", "9", { force: "1", charge2: "1", distance: "3.5" })

		expect(latexOf(steps[3])).toBe(String.raw`q=\dfrac{12.25}{9\times10^{9}}`)
	})

	it("accepts values that overflowed a double before", () => {
		const { steps } = calculate("force", "9", { charge1: "1e300", charge2: "1e300", distance: "1" })

		expect(latexOf(steps.at(-1)!)).toBe(String.raw`F=9\times10^{609}\N`)
	})

	it("accepts a comma as the decimal separator", () => {
		const point = calculate("force", "9", { charge1: "0.5", charge2: "2", distance: "3" })
		const comma = calculate("force", "9", { charge1: "0,5", charge2: "2", distance: "3" })

		expect(comma).toEqual(point)
	})

	it("accepts a charge of zero when calculating the force", () => {
		const { steps } = calculate("force", "9", { charge1: "0", charge2: "1", distance: "1" })

		expect(latexOf(steps.at(-1)!)).toBe(String.raw`F=0\N`)
	})

	it("accepts the limits of Coulomb's constant", () => {
		expect(() => calculate("force", "8.9", { charge1: "1", charge2: "1", distance: "1" })).not.toThrow()
		expect(() => calculate("force", "9", { charge1: "1", charge2: "1", distance: "1" })).not.toThrow()
	})

	it.each([
		["force", "9", { charge1: "", charge2: "1", distance: "1" }, "missing", "charge1"],
		["force", "9", { charge1: "abc", charge2: "1", distance: "1" }, "invalid", "charge1"],
		["force", "9", { charge1: "1", charge2: "1,5,2", distance: "1" }, "invalid", "charge2"],
		["force", "9", { charge1: "1e1001", charge2: "1", distance: "1" }, "exponent", "charge1"],
		["force", "8.8", { charge1: "1", charge2: "1", distance: "1" }, "constantRange", "constant"],
		["force", "9.1", { charge1: "1", charge2: "1", distance: "1" }, "constantRange", "constant"],
		["force", "", { charge1: "1", charge2: "1", distance: "1" }, "missing", "constant"],
		["force", "abc", { charge1: "1", charge2: "1", distance: "1" }, "invalid", "constant"],
		["force", "9", { charge1: "1", charge2: "1", distance: "0" }, "distanceNotPositive", "distance"],
		["charge", "9", { force: "1", charge2: "1", distance: "-2" }, "distanceNotPositive", "distance"],
		["charge", "9", { force: "-1", charge2: "1", distance: "2" }, "forceNegative", "force"],
		["charge", "9", { force: "1", charge2: "0", distance: "2" }, "chargeZero", "charge2"],
		["distance", "9", { force: "0", charge1: "1", charge2: "1" }, "forceNotPositive", "force"],
		["distance", "9", { force: "-3", charge1: "1", charge2: "1" }, "forceNotPositive", "force"]
	] as const)("rejects invalid input: %s %s %j", (id, constant, values, code, field) => {
		expect(() => calculate(id, constant, values)).toThrow(new CalculationError(code, field))
	})
})
